// Based on String.prototype.supplant in Douglas Crockford's "Remedial JavaScript"
export function stringInterpolate(format: string, values: { [index: string]: any }): string {
    return format.replace(/\${([^${}]*)}/g,
        function (substring: string, key: string): string {
            const value = values[key];
            if (typeof value === 'string') {
                return value;
            }
            if (typeof value === 'number') {
                return value.toString();
            }
            return substring;
        }
    );
}
